#!/bin/bash
cd /home/nolan/projects/ping
echo "=== pre git status ==="
git status --porcelain | head -10
test -x node_modules/.bin/jest && echo "jest present" || { echo "JEST MISSING"; exit 3; }
base64 -d > src/fyd/sitespec/__tests__/zz-hostile-seam.test.ts <<'B64EOF'

B64EOF
mkdir -p /tmp/hostile-pipe
npx jest --config src/fyd/sitespec/jest.config.cjs zz-hostile-seam > /tmp/hostile-pipe/jest.log 2>&1
echo "jest exit: $?"
grep -E "Tests:|Test Suites:" /tmp/hostile-pipe/jest.log | tail -4
awk '/HOSTILE_JSON_BEGIN/{f=1;next}/HOSTILE_JSON_END/{f=0}f' /tmp/hostile-pipe/jest.log > /tmp/hostile-pipe/results.json
echo "results bytes: $(wc -c < /tmp/hostile-pipe/results.json)"
cat /tmp/hostile-pipe/results.json
rm -rf /tmp/hostile-pipe
rm -f src/fyd/sitespec/__tests__/zz-hostile-seam.test.ts
echo "=== post git status (zz-hostile refs) ==="
git status --porcelain | grep "zz-hostile" || echo "temp file gone, tree clean of harness"
